#include <cstdio>

struct Empty {};

// C++20：允许无状态成员与其它成员共享地址
struct WithNUA    { [[no_unique_address]] Empty e; int x; };
struct WithoutNUA { Empty e; int x; };

struct Alloc {};                                  // 无状态分配器
struct Holder { [[no_unique_address]] Alloc a; int* ptr; };

int main() {
    printf("no_unique_address sizeof=%zu 普通成员 sizeof=%zu\n",
           sizeof(WithNUA), sizeof(WithoutNUA));
    printf("无状态分配器不占空间: %d\n",
           (int)(sizeof(Holder) == sizeof(int*)));
    printf("对比省下 %zu 字节\n", sizeof(WithoutNUA) - sizeof(WithNUA));
    return 0;
}
